// Get whatever Aggregate produced
const raw = $input.first().json.output;

// Flatten in case it's an array of arrays, then join everything into one string
function flatten(data) {
  if (Array.isArray(data)) {
    return data.map(flatten).join("\n\n");
  }
  return String(data);
}

let fullText = flatten(raw);

// Clean up literal backslash-n, backslash-quote, and stray backslashes
fullText = fullText
  .replace(/\\n/g, " ")     // literal backslash-n
  .replace(/\\"/g, '"')     // escaped quotes -> normal quotes
  .replace(/\\/g, "");      // any remaining stray backslashes

fullText = fullText.replace(/\s+/g, " ").trim();

return [{ json: { full_text: fullText } }];

// n8n Code node — JavaScript
// Input: expects the full story text somewhere in the incoming item, e.g. $json.story_text
// Output: one item per sentence, in order, each with a scene_index

const fullText = $input.first().json.full_text; // adjust field name to match your actual data

let cleaned = fullText.replace(/\s+/g, " ").trim();

// Protect "..." so it isn't mistaken for 3 separate sentence-endings
cleaned = cleaned.replace(/\.\.\./g, "<ELLIPSIS>");

const rawSentences = cleaned.match(/[^.!?]+[.!?]+(\s+|$)/g) || [cleaned];

let sentences = rawSentences
  .map(s => s.replace(/<ELLIPSIS>/g, "...").trim())
  .filter(s => s.length > 0);

// Merge stray short fragments (usually caused by quote marks or dashes breaking
// a sentence awkwardly) into the previous sentence instead of leaving them standalone
const merged = [];
for (const s of sentences) {
  if (merged.length > 0 && s.length < 25) {
    merged[merged.length - 1] = merged[merged.length - 1] + " " + s;
  } else {
    merged.push(s);
  }
}

const scenes = merged.map((text, index) => ({
  scene_index: index,
  text: text,
}));

return scenes.map(scene => ({ json: scene }));

