if (Array.isArray(aiOutput.characters)) {
  aiCharacters = aiOutput.characters;
} else if (typeof aiOutput.characters === 'string') {
  try {
    aiCharacters = JSON.parse(aiOutput.characters);
  } catch (e) {
    aiCharacters = [];
  }
} else if (aiOutput.characters && typeof aiOutput.characters === 'object') {
  aiCharacters = Object.values(aiOutput.characters);
}

