// n8n Code node — JavaScript
const sentenceItems = $('Code in JavaScript1').all().map(item => item.json);
const timingResponse = $('HTTP Request').first().json;
const timings = timingResponse.scenes || [];
const minCount = Math.min(sentenceItems.length, timings.length);

const CHUNK_SECONDS = 10; // max length for any leftover scene

const combined = [];
for (let i = 0; i < minCount; i++) {
  combined.push({
    scene_index: i,
    text: sentenceItems[i].text,
    start: timings[i].start,
    end: timings[i].end,
    previous_text: i > 0 ? sentenceItems[i - 1].text : "",
  });
}

if (timings.length > sentenceItems.length && combined.length > 0) {
  // Leftover timing beyond the last matched sentence.
  const lastText = sentenceItems[sentenceItems.length - 1].text;
  const leftoverStart = timings[minCount - 1].end; // where the last matched scene currently ends
  const trueEnd = timings[timings.length - 1].end;

  let cursor = leftoverStart;
  while (cursor < trueEnd) {
    const chunkEnd = Math.min(cursor + CHUNK_SECONDS, trueEnd);
    combined.push({
      scene_index: combined.length,
      text: lastText,
      start: cursor,
      end: chunkEnd,
      previous_text: lastText,
    });
    cursor = chunkEnd;
  }
} else if (sentenceItems.length > timings.length && combined.length > 0) {
  const extraText = sentenceItems.slice(minCount).map(s => s.text).join(" ");
  combined[combined.length - 1].text += " " + extraText;
}

if (sentenceItems.length !== timings.length) {
  console.log(
    `Note: ${sentenceItems.length} sentences vs ${timings.length} timings — leftover handled (chunked in ${CHUNK_SECONDS}s pieces if extra timing).`
  );
}

return combined.map(scene => ({ json: scene }));

