// n8n Code node — paste this right after your "Combine Sentences With Timing" node.
// Assumes each input item has: text, start (seconds), end (seconds)
// If your field names are different (e.g. startTime/endTime, or milliseconds),
// adjust the destructuring line below to match.

function formatSRTTime(seconds) {
  const h = Math.floor(seconds / 3600);
  const m = Math.floor((seconds % 3600) / 60);
  const s = Math.floor(seconds % 60);
  const ms = Math.round((seconds % 1) * 1000);
  return `${String(h).padStart(2,'0')}:${String(m).padStart(2,'0')}:${String(s).padStart(2,'0')},${String(ms).padStart(3,'0')}`;
}

