// Purpose: take the names the LLM said are present in THIS sentence, and look
// up their already-locked image URLs from Code in JavaScript2's cast list.
// Also attaches the one fixed background_url (same for every scene).
//
// Place this AFTER the per-sentence casting LLM node (the one using
// prompt_scene_casting.txt), inside your per-scene loop.

const castList = $('Code in JavaScript4').first().json.characters; // [{name, folder, file, url}, ...]
const backgroundUrl = $('Code in JavaScript4').first().json.background_url;

// Build a quick lookup: name -> url
const nameToUrl = {};
for (const c of castList) {
  nameToUrl[c.name] = c.url;
}

// The LLM's output for this sentence — handle it whether it's a raw JSON string
// (no output parser attached) or already a parsed object (parser attached)
let llmOutput = $input.first().json.output || $input.first().json;

if (typeof llmOutput === "string") {
  try {
    llmOutput = JSON.parse(llmOutput);
  } catch (e) {
    llmOutput = { characters: [] }; // couldn't parse — safely default to no characters
  }
}

const namesPresent = (llmOutput.characters || []).slice(0, 3);

function findUrl(name) {
  // Try an exact match first
  if (nameToUrl[name]) return nameToUrl[name];

  // Fallback: maybe the model shortened the name (e.g. "Wang" instead of
  // "Mei-Xing Wang"). Look for cast names containing this word — but only
  // use it if exactly ONE cast member matches, to avoid guessing wrong.
  const lowerName = name.toLowerCase();
  const matches = Object.keys(nameToUrl).filter(fullName =>
    fullName.toLowerCase().includes(lowerName) || lowerName.includes(fullName.toLowerCase())
  );
  if (matches.length === 1) return nameToUrl[matches[0]];

  return undefined; // no confident match — drop it rather than guess wrong
}

const staticData = $getWorkflowStaticData('node');
if (!staticData.lastCharacterUrls) staticData.lastCharacterUrls = [];

let characterUrls = namesPresent
  .map(name => findUrl(name))
  .filter(url => url !== undefined);

if (characterUrls.length === 0 && staticData.lastCharacterUrls.length > 0) {
  // No character resolved this sentence — most likely the same character(s)
  // from the previous scene are still on screen and just weren't re-named.
  characterUrls = staticData.lastCharacterUrls;
}

staticData.lastCharacterUrls = characterUrls;
